/* @autogenerated */
import { Component, inject } from '@angular/core';
import { TemplateAsset } from 'app/features/template/template-asset/model/template-asset.model';
import { TemplateAssetRepository } from 'app/features/template/template-asset/repository/template-asset-repository.service';
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';

@Component({ selector: 'template-asset-view-enable-action', standalone: false, template: '' })
export class TemplateAssetViewEnableActionComponent extends ConfirmAction<TemplateAsset> {
  readonly name = 'enable';
  protected readonly scope = 'template/template-asset';
  protected readonly repository = inject(TemplateAssetRepository);

  protected override appliesTo(items: TemplateAsset[]) {
    return items.every((item) => !item.enabled);
  }

  protected execute([item]: TemplateAsset[]) {
    return this.repository.enable(item.uid);
  }
}
